AttributeRule.ScriptExpression:
// Get the current value of the "Dataset Name" field
                            var currentValue = $feature.DATASET_NAME;

                            // Count the occurrences of the current value in the "Dataset Name" field
                            var duplicateCount = Count(Filter($featureSet, "DATASET_NAME = '" +
                            currentValue + "'"));

                            // Return an error message if there are duplicates
                            if (duplicateCount > 1) {
                            return False;
                            }

                            // No duplicates, return null (no error)
                            return True;
